--
-- Name: ml_features; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ml_features AS
 SELECT l.loan_id,
    l.client_id,
    l.loan_intent,
    l.loan_grade,
    l.loan_amnt,
    l.loan_int_rate,
    l.loan_percent_income,
    l.debt_to_income_ratio,
    l.loan_status,
    c.age,
    c.income,
    c.home_ownership,
    c.emp_length,
    cb.default_on_file,
    cb.cred_hist_length,
    cb.credit_utilization_ratio,
    cb.past_delinquencies,
    ci.country
   FROM (((public.loans l
     JOIN public.customers c ON (((c.client_id)::text = (l.client_id)::text)))
     JOIN public.credit_bureau cb ON (((cb.client_id)::text = (l.client_id)::text)))
     LEFT JOIN public.cities ci ON ((ci.city_id = c.city_id)))
  WHERE ((l.data_source)::text = 'historical'::text);


