CREATE VIEW public.dashboard_aggregates AS
 SELECT loan_id,
    client_id,
    loan_intent,
    loan_grade,
    loan_amnt,
    loan_int_rate,
    loan_percent_income,
    debt_to_income_ratio,
    loan_status,
    age,
    income,
    home_ownership,
    emp_length,
    default_on_file,
    cred_hist_length,
    credit_utilization_ratio,
    past_delinquencies,
    country,
    avg(loan_amnt) OVER (PARTITION BY ((age / 10) * 10)) AS avg_loan_amnt_by_age_bucket,
    avg((loan_status)::numeric) OVER (PARTITION BY loan_grade) AS default_rate_by_grade,
    rank() OVER (PARTITION BY country ORDER BY credit_utilization_ratio DESC) AS util_rank_in_country
   FROM public.ml_features;


